// src/App.jsx
import { useState } from "react";
import ValidationAffectations from "./components/ValidationAffectations";
import PlanningFinal from "./components/PlanningFinal";

const TABS = [
  { id: "phase1", label: "Phase 1 — Validation",      emoji: "✅" },
  { id: "phase2", label: "Phase 2 — Disponibilités",  emoji: "📅" },
  { id: "phase3", label: "Phase 3 — Planification",   emoji: "🗓️" },
  { id: "phase4", label: "Phase 4 — Planning final",  emoji: "📋" },
];

export default function App() {
  const [active, setActive] = useState("phase1");

  return (
    <div style={{ minHeight: "100vh", background: "#F9FAFB", fontFamily: "sans-serif" }}>

      {/* Header */}
      <div style={{ background: "#fff", borderBottom: "1px solid #E5E7EB", padding: "0 24px" }}>
        <div style={{ maxWidth: 900, margin: "0 auto" }}>
          <div style={{ padding: "16px 0 0", fontSize: 20, fontWeight: 700, color: "#111827" }}>
            Gestion PFA — Soutenances
          </div>
          <div style={{ display: "flex", gap: 4, marginTop: 12 }}>
            {TABS.map(t => (
              <button key={t.id} onClick={() => setActive(t.id)}
                style={{
                  padding: "10px 16px",
                  border: "none",
                  borderBottom: active === t.id ? "2px solid #6366F1" : "2px solid transparent",
                  background: "none",
                  cursor: "pointer",
                  fontSize: 13,
                  fontWeight: active === t.id ? 600 : 400,
                  color: active === t.id ? "#6366F1" : "#6B7280",
                  whiteSpace: "nowrap",
                }}>
                {t.emoji} {t.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Contenu */}
      <div style={{ maxWidth: 900, margin: "0 auto", padding: "24px 16px" }}>
        {active === "phase1" && <ValidationAffectations />}
        {active === "phase2" && <DisponibilitesPlaceholder />}
        {active === "phase3" && <PlanificationPlaceholder />}
        {active === "phase4" && <PlanningFinal />}
      </div>
    </div>
  );
}

// Placeholder Phase 2 — tu peux développer ce composant
function DisponibilitesPlaceholder() {
  return (
    <div style={{ textAlign: "center", padding: 60, color: "#6B7280" }}>
      <div style={{ fontSize: 48 }}>📅</div>
      <h3 style={{ marginTop: 16 }}>Phase 2 — Gestion des disponibilités</h3>
      <p>Composant à développer : créneaux + disponibilités des profs.</p>
      <p style={{ fontSize: 13 }}>Endpoints disponibles : GET/POST /api/creneaux · GET/POST /api/disponibilites</p>
    </div>
  );
}

// Placeholder Phase 3 — tu peux développer ce composant
function PlanificationPlaceholder() {
  return (
    <div style={{ textAlign: "center", padding: 60, color: "#6B7280" }}>
      <div style={{ fontSize: 48 }}>🗓️</div>
      <h3 style={{ marginTop: 16 }}>Phase 3 — Planification des soutenances</h3>
      <p>Composant à développer : assignation binôme → créneau → jury.</p>
      <p style={{ fontSize: 13 }}>Endpoints : POST /api/soutenances/planifier · POST /api/soutenances/planifier-auto</p>
    </div>
  );
}
